CREATE INDEX idx_runtime_key_bindings_run ON runtime_key_bindings (run_id);
CREATE TABLE "deployment_baselines" ("target_id" TEXT NOT NULL,"target_identity" TEXT NOT NULL,"registration_id" TEXT NOT NULL,"source_run_id" TEXT NOT NULL,"revision" TEXT NOT NULL,"payload" TEXT NOT NULL,"available" numeric NOT NULL,PRIMARY KEY ("target_id"),CHECK (available IN (0,1)));
CREATE TABLE "restore_points" ("id" TEXT NOT NULL,"target_id" TEXT NOT NULL,"target_identity" TEXT NOT NULL,"registration_id" TEXT NOT NULL,"source_run_id" TEXT NOT NULL,"created_at" datetime NOT NULL,"source_state" TEXT NOT NULL,"revision" TEXT NOT NULL,"payload" TEXT NOT NULL,"available" numeric NOT NULL,PRIMARY KEY ("id"),CHECK (available IN (0,1)),CHECK (source_state IN ('settled','partial-source')));
CREATE TABLE "image_lifecycle_runs" ("id" TEXT NOT NULL,"point_id" TEXT NOT NULL,"selected_point_id" TEXT NOT NULL,"had_effect" numeric NOT NULL,"settled" numeric NOT NULL,PRIMARY KEY ("id"),CHECK (had_effect IN (0,1)),CHECK (settled IN (0,1)));
CREATE TABLE "runtime_image_intents" ("run_id" TEXT NOT NULL,"payload" TEXT NOT NULL,PRIMARY KEY ("run_id"));
CREATE INDEX `idx_restore_points_target_created` ON `restore_points`(`target_id`,`created_at`);
